 968	      \subsection{Applying the classical low-degree test}
 969	      \label{sec:apply-ldt}
 970	      In the previous section we showed how to combine the
 971	      approximately commuting $X$ and $Z$ basis point and line
 972	      measurements into a joint point measurement and a joint line
 973	      measurement. In this section we show how these measurements can be combined
 974				in a single measurement
 975	      that returns a pair of global polynomials encoding the $X$-basis and
 976	      $Z$-basis information, respectively, by applying the lemma that states quantum soundness of the classical low-degree test, Theorem~\ref{lem:ld-soundness}.
 977				
 978	      Introduce a ``combining'' map that
 979	      takes two polynomials $f, g \in \ideg_{d,m}(\F_q)$ and returns a new polynomial $\combine_{f,g} \in \ideg_{d,
 980	        2m+2}(\F_q)$ defined by
 981	      \[ \combine_{f,g}(\underbrace{x}_{\in \F_q^{m}},
 982	        \underbrace{z}_{\in \F_q^m}, \underbrace{\alpha}_{\in \F_q},
 983	        \underbrace{\beta}_{\in \F_q}) = \alpha f(x) + \beta g(z)\;. \]
 984	      This combining map can also be defined for polynomials restricted to lines. Let $\line$ be a line in $\F_q^{2m+2}$ with intercept $u = (u_X, u_Z, u_\alpha, u_\beta)$ and slope $v = (v_X, v_Z, v_\alpha, v_\beta)$. Let $\line_X$ and $\line_Z$ be lines in $\F_q^{m}$ such that for any point $(x,z,\alpha,\beta) \in \line$, it holds that $x \in \line_X$ and $z \in \line_Z$. Then for any two polynomials $f \in \deg_{dm}(\line_X)$ and $g \in \deg_{dm}(\line_Z)$, we define $\combine_{f,g} \in \deg_{dm + 1}(\line)$ by
 985	      \begin{equation}
 986	        \combine_{f,g}(u + t \cdot v) = (u_\alpha + t\cdot v_\alpha) f(u_X + t \cdot v_X) + (u_\beta + t \cdot v_\beta) g(u_Z + t \cdot v_Z)\;. \label{eq:combine-lines}
 987	      \end{equation}
 988	      
 989	
 990	      In the following two lemma we define combined point and line
 991	      measurements according to this definition of $\combine_{f,g}$.
 992	
 993	\begin{lemma}\label{lem:qld-4-12}
 994		For all $x,z \in \F_q^m$ and $\alpha,\beta \in \F_q$ and $\mH \in \{ \mH_\alice, \mH_\bob\}$ there exists a projective measurement $\{ \hat{Q}^{x,z,\alpha,\beta}_c \}_{c \in \F_q}$ acting on $\mathcal{H} \otimes (\C^q)^{\otimes \nqubits}$ such that the following holds:
 995		\begin{enumerate}
 996			\item (\textbf{Self-consistency}) On average over uniformly random $(x,z,\alpha,\beta) \in \F_q^{2m + 2}$:
 997			\begin{equation}
 998				\label{eq:qld-4-12-self-cons}
 999				(\hat{Q}^{x,z,\alpha,\beta}_{c})_{\alice \alice'} \approx_{\delta_Q}  (\hat{Q}^{x,z,\alpha,\beta}_{c})_{\bob \alice''}\,.
1000			\end{equation}
1001	\item (\textbf{Consistency with $\hat{M}$}) On average over uniformly random $(x,z,\alpha,\beta) \in \F_q^{2m + 2}$:
1002			\begin{gather}
1003				\label{eq:qld-4-12-cons-m-hat}
1004				(\hat{Q}^{x,z,\alpha,\beta}_{c})_{\alice \alice'} \approx_{\delta_Q} \Big ( \sum_{\substack{a,b: \\ \alpha a + \beta b = c}} \hat{M}^{(\Point,X),x}_{a} \hat{M}^{(\Point,Z),z}_{b} \Big )_{\bob \alice''} \;, \\
1005				\label{eq:qld-4-12-cons-m-hat2}
1006				(\hat{Q}^{x,z,\alpha,\beta}_{c})_{\alice \alice'} \approx_{\delta_Q}  \Big ( \sum_{\substack{a,b: \\ \alpha a + \beta b = c}} \hat{M}^{(\Point,Z),z}_{b} \, \hat{M}^{(\Point,X),x}_{a}  \Big )_{\bob \alice''}  \,.			
1007			\end{gather}
1008	              \end{enumerate}
1009	                    Furthermore, all symmetric equivalents of these approximations
1010	      also hold.
1011	\end{lemma}
1012	\begin{proof}
1013		Define 
1014		\[
1015			\hat{Q}^{x,z,\alpha,\beta}_{c} = \sum_{\substack{a,b:\\ \alpha a + \beta b = c}} \hat{Q}^{x,z}_{a,b}.
1016		\]
1017		The self-consistency and consistency properties of $\{ \hat{Q}^{x,z,\alpha,\beta}_{c} \}$ follow from the consistency properties of $\{ \hat{Q}^{x,z}_{a,b} \}$ established by Lemma~\ref{lem:qld-4-10}, and Fact~\ref{fact:data-processing}. 
1018	\end{proof}
1019	
1020	\begin{lemma}\label{lem:qld-4-13}
1021	There exists a function $\delta_{\combine}(\eps,m,d,q) = \poly(m^2\eps,md/q)$ such that the following holds. 
1022	For every line $\line$ in
1023	$\F_q^{2m + 2}$ and $\mH \in \{ \mH_\alice,\mH_\bob\}$ there exists a POVM $\{ \hat{Q}^\line_f \}$ acting on
1024	$\mathcal{H} \otimes (\C^q)^{\otimes \nqubits}$ with outcomes $f\in
1025	\deg_{md+1}(\line)$ such that on average over a uniformly random
1026	pair $(\line, (x,z,\alpha, \beta))$ drawn from the line-point
1027	distribution over $\F_q^{2m+2}$,
1028	\begin{gather}
1029	\label{eq:qld-4-13}
1030	(\hat{Q}^\line_{[\eval_{(x,z,\alpha,\beta)}(\cdot) = a]})_{\alice \alice'} \simeq_{\delta_{\combine}} (\hat{Q}^{x,z,\alpha,\beta}_{a} )_{\bob \alice''}\;, \\
1031	(\hat{Q}^\line_{[\eval_{(x,z,\alpha,\beta)}(\cdot) = a]})_{\bob \bob'} \simeq_{\delta_{\combine}} ( \hat{Q}^{x,z,\alpha,\beta}_{a} )_{\alice \bob''}\;,
1032	\end{gather}
1033	where the answer summation is over $a \in \F_q$. Moreover, if $\line$ is axis-parallel, then the outcome $f \in \deg_{d}(\line)$.
1034	\end{lemma}
